const DAY_MS = 86_400_000;

export function getReferenceDayEnergy(date: string): ReferenceDayEnergy | null {
  const match = date.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return null;
  const index = Math.floor((Date.UTC(Number(match[1]), Number(match[2]) - 1, Number(match[3])) - REFERENCE_START) / DAY_MS);
  const row = REFERENCE_DAYS[index];
  return row ? { score: row[0], advice: ADVICE[row[1]] } : null;
}
